-- TitanGlobal ERP: licitaciones y ofertas de proveedores (módulo 14, spec modulo14-licitaciones-backend).
--
-- Una licitación (concurso de precios o subasta inversa) recibe una oferta por proveedor. Al adjudicarla se guardan
-- el proveedor y el monto ganadores. Las reglas CK_ repiten en la base lo que ya valida la API, como segunda defensa
-- ante datos cargados por fuera. Convención de nombres: CK_<Tabla>_<Regla>.

CREATE TABLE "Licitaciones" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Numero" character varying(20) NOT NULL,
    "Titulo" character varying(150) NOT NULL,
    "Descripcion" character varying(500),
    "Tipo" character varying(20) NOT NULL,
    "Estado" character varying(20) NOT NULL,
    "PresupuestoReferencial" numeric(18,2) NOT NULL,
    "FechaCierre" timestamp with time zone NOT NULL,
    "ProveedorAdjudicadoId" integer,
    "MontoAdjudicado" numeric(18,2),
    "FechaRegistro" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Licitaciones" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Licitaciones_Proveedores_ProveedorAdjudicadoId" FOREIGN KEY ("ProveedorAdjudicadoId") REFERENCES "Proveedores" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_Licitaciones_Tipo" CHECK ("Tipo" IN ('ConcursoPrecios', 'SubastaInversa')),
    CONSTRAINT "CK_Licitaciones_Estado" CHECK ("Estado" IN ('Abierta', 'Cerrada', 'Adjudicada', 'Cancelada')),
    CONSTRAINT "CK_Licitaciones_PresupuestoReferencial" CHECK ("PresupuestoReferencial" > 0),
    CONSTRAINT "CK_Licitaciones_AdjudicacionCoherente" CHECK (
        ("Estado" = 'Adjudicada' AND "ProveedorAdjudicadoId" IS NOT NULL AND "MontoAdjudicado" IS NOT NULL)
        OR ("Estado" <> 'Adjudicada' AND "ProveedorAdjudicadoId" IS NULL AND "MontoAdjudicado" IS NULL))
);
CREATE UNIQUE INDEX "IX_Licitaciones_Numero" ON "Licitaciones" ("Numero");
CREATE INDEX "IX_Licitaciones_ProveedorAdjudicadoId" ON "Licitaciones" ("ProveedorAdjudicadoId");

CREATE TABLE "OfertasLicitacion" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "LicitacionId" integer NOT NULL,
    "ProveedorId" integer NOT NULL,
    "Monto" numeric(18,2) NOT NULL,
    "PlazoEntregaDias" integer NOT NULL,
    "Observaciones" character varying(500),
    "FechaRegistro" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_OfertasLicitacion" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OfertasLicitacion_Licitaciones_LicitacionId" FOREIGN KEY ("LicitacionId") REFERENCES "Licitaciones" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_OfertasLicitacion_Proveedores_ProveedorId" FOREIGN KEY ("ProveedorId") REFERENCES "Proveedores" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_OfertasLicitacion_Monto" CHECK ("Monto" > 0),
    CONSTRAINT "CK_OfertasLicitacion_PlazoEntregaDias" CHECK ("PlazoEntregaDias" BETWEEN 1 AND 365)
);
CREATE UNIQUE INDEX "IX_OfertasLicitacion_LicitacionId_ProveedorId" ON "OfertasLicitacion" ("LicitacionId", "ProveedorId");
CREATE INDEX "IX_OfertasLicitacion_ProveedorId" ON "OfertasLicitacion" ("ProveedorId");
